interface.definition:
a!localVariables(
  local!reportMap: {
    a!map(
      reportName: "Nomination",
      chooseId: 2,
      description: "Nomination Export",
      icon: "address-card-o",
      visibility: true
    ),
    a!map(
      reportName: "Core ASK",
      chooseId: 3,
      description: "Core ASK Export",
      icon: "list-alt",
      visibility: true
    ),
    a!map(
      reportName: "Rotational ASK",
      chooseId: 4,
      description: "Rotational ASK Export",
      icon: "list-alt",
      visibility: true
    ),
    a!map(
      reportName: "Candidate Intake",
      chooseId: 5,
      description: "Candidate Intake Export",
      icon: "file-excel",
      visibility: true
    ),
    a!map(
      reportName: "Nomination vs ASK",
      chooseId: 6,
      description: "The Nomination vs ASK Summary Report",
      icon: "table",
      visibility: true
    ),
    a!map(
      reportName: "ASK Summary Dashboard",
      chooseId: 7,
      description: "Dashboard for ASK Summaries",
      icon: "pie-chart",
      visibility: true
    )
  },
  choose(
    ri!chooseId,
    #"SYSTEM_SYSRULES_cardLayout"(
      padding: "MORE",
      style: "STANDARD",
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: #"SYSTEM_SYSRULES_forEach"(
            items: index(local!reportMap,{1,2,3,4}),
            expression: #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_cardLayout"(
                  showWhen: fv!item.visibility,
                  padding: "STANDARD",
                  shape: "SEMI_ROUNDED",
                  height: "MEDIUM_PLUS",
                  style: "ACCENT",
                  link: #"SYSTEM_SYSRULES_dynamicLink"(
                    saveInto: {
                      a!save(ri!chooseId, fv!item.chooseId),
                      a!save(ri!showHomePage,false)
                    }
                  ),
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      align: "CENTER",
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: fv!item.icon,
                          size: "LARGE_PLUS"
                        ),
                        char(10),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: fv!item.reportName,
                          style: "STRONG",
                          size: "MEDIUM_PLUS"
                        ),
                        char(10),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(size: "SMALL", text: fv!item.description)
                      }
                    )
                  }
                )
              }
            )
          )
        ),
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_forEach"(
            items: index(local!reportMap,{5,6}),
            expression: #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_cardLayout"(
                  showWhen: fv!item.visibility,
                  padding: "STANDARD",
                  shape: "SEMI_ROUNDED",
                  height: "MEDIUM_PLUS",
                  style: "ACCENT",
                  link: #"SYSTEM_SYSRULES_dynamicLink"(
                    saveInto: {
                      a!save(ri!chooseId, fv!item.chooseId),
                      a!save(ri!showHomePage,false)
                    }
                  ),
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      align: "CENTER",
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: fv!item.icon,
                          size: "LARGE_PLUS"
                        ),
                        char(10),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: fv!item.reportName,
                          style: "STRONG",
                          size: "MEDIUM_PLUS"
                        ),
                        char(10),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(size: "SMALL", text: fv!item.description)
                      }
                    )
                  }
                )
              }
            )
          ),
            #"SYSTEM_SYSRULES_columnLayout"(),
            #"SYSTEM_SYSRULES_columnLayout"()
          }
        )
      }
    ),
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5158601"(chooseId: ri!chooseId),
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5242870"(chooseId: ri!chooseId),
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5247639"(chooseId: ri!chooseId),
    #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6758744"(chooseId: ri!chooseId),
    #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6616544"(),
    #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6730820"()
  )
)
